// Dev-only missing-translation detector: when EN is active and a key passes through
// untranslated (heuristic: contains non-ASCII chars typical of Swahili), record it so
// the offline audit (scripts/translation-audit.cjs) can be re-run to close the gap.
declare global {
  interface Window {
    __missingTranslations?: string[];
  }
}
function logMissingEnTranslation(text: string): void {
  try {
    if (!/[^\x00-\x7F]/.test(text)) return;
    const w = window as Window;
    if (!w.__missingTranslations) w.__missingTranslations = [];
    if (!w.__missingTranslations.includes(text)) {
      w.__missingTranslations.push(text);
      console.debug('[i18n] missing EN translation:', text);
    }
  } catch (e) {}
}

export function translate(text: string, language: 'en' | 'sw' | 'fr' | 'es' | string): string {
  if (language === 'en') {
    const mapped = pageTitleMap[text] || englishDict[text];
    if (!mapped && typeof window !== 'undefined') logMissingEnTranslation(text);
    return mapped || text;
  }
  const englishText = pageTitleMap[text] || text;
  if (language === 'sw') {
    return swahiliDict[text] || swahiliDict[englishText] || englishText;
  }
  if (language === 'fr') {
    const fr = frenchDict[text];
    if (fr) return fr;
    const fr2 = frenchDict[englishText];
    return fr2 || englishText;
  }
  if (language === 'es') {
    const es = spanishDict[text];
    if (es) return es;
    const es2 = spanishDict[englishText];
    return es2 || englishText;
  }
  return englishText;
}

export type CurrencyType = 'USD' | 'TZS' | 'KES' | 'UGD' | 'UGX' | 'RWF' | 'EUR' | 'GBP';

export function formatMoney(amount: number, currency: string, exchangeRate: number): string {
  const rate = currency === 'USD' ? 1 : exchangeRate;
  const convertedAmount = amount * rate;
  
  const symbols: Record<string, string> = {
    USD: '$',
    TZS: 'TSh ',
    KES: 'KSh ',
    UGD: 'USh ',
    UGX: 'USh ',
    RWF: 'RF ',
    EUR: '€',
    GBP: '£'
  };
  const symbol = symbols[currency] !== undefined ? symbols[currency] : `${currency} `;
  
  const zeroDecimalCurrencies = ['TZS', 'KES', 'UGD', 'UGX', 'RWF'];
  const decimals = zeroDecimalCurrencies.includes(currency) ? 0 : 2;
  
  return symbol + convertedAmount.toLocaleString('en-US', {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals
  });
}

export function exportToExcel(htmlTableString: string, filename: string) {
  const template = `
    <html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">
    <head>
      <!--[if gte mso 9]>
      <xml>
        <x:ExcelWorkbook>
          <x:ExcelWorksheets>
            <x:ExcelWorksheet>
              <x:Name>Sheet1</x:Name>
              <x:WorksheetOptions>
                <x:DisplayGridlines/>
              </x:WorksheetOptions>
            </x:ExcelWorksheet>
          </x:ExcelWorksheets>
        </x:ExcelWorkbook>
      </xml>
      <![endif]-->
      <meta charset="utf-8">
      <style>
        table { border-collapse: collapse; font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; }
        th { background-color: #ef4444; color: white; font-weight: bold; border: 1px solid #cbd5e1; padding: 10px; text-align: left; }
        td { border: 1px solid #e2e8f0; padding: 8px; text-align: left; }
        tr:nth-child(even) { background-color: #f8fafc; }
        .text-right { text-align: right; }
        .font-bold { font-weight: bold; }
        .bg-red-50 { background-color: #fef2f2; }
        .text-red-600 { color: #dc2626; }
      </style>
    </head>
    <body>
      ${htmlTableString}
    </body>
    </html>
  `;
  const blob = new Blob([template], { type: 'application/vnd.ms-excel;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename.endsWith('.xls') ? filename : `${filename}.xls`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

